func TestSiblingLeafCannotInterceptAnotherChild(t *testing.T) {
	ctx, cancel := context.WithTimeout(t.Context(), 60*time.Second)
	defer cancel()
	gru, gruRuntime, sfoRuntime, addr, leafTLS := startHubWithChild(ctx, t)

	sfoQuery, err := sfoRuntime.Conn().Subscribe(protocol.Regional("sfo", "query", "status"), func(msg *nats.Msg) {
		_ = msg.Respond([]byte("sfo-ok"))
	})
	if err != nil {
		t.Fatal(err)
	}
	defer sfoQuery.Unsubscribe()
	if err := sfoRuntime.Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	if reply := requestUntil(ctx, t, gruRuntime.Conn(), protocol.Regional("sfo", "query", "status")); string(reply.Data) != "sfo-ok" {
		t.Fatalf("baseline query = %q", reply.Data)
	}
	assertObservabilityCrossesNarrowly(ctx, t, gruRuntime, sfoRuntime)

	sibling := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-leaf.creds", "fra"))
	defer sibling.close()
	for _, wildcard := range []string{"ts.orch.v1.sfo.>", "ts.orch.v1.*.query.>", "ts.interregion.v1.>", ">"} {
		sibling.subscribe(t, wildcard)
	}
	time.Sleep(300 * time.Millisecond)
	for range 5 {
		reply := requestUntil(ctx, t, gruRuntime.Conn(), protocol.Regional("sfo", "query", "status"))
		if string(reply.Data) != "sfo-ok" {
			t.Fatalf("query to SFO answered by someone else: %q", reply.Data)
		}
	}
	// SFO's mirror feed and its observability requests are SFO's alone too.
	for range 5 {
		if err := gruRuntime.Conn().Publish(protocol.InterRegionGlobalDeliverSubject("sfo"), []byte("feed")); err != nil {
			t.Fatal(err)
		}
		for _, leaf := range protocol.InterRegionObservabilityLeaves() {
			requestCtx, requestCancel := context.WithTimeout(ctx, 200*time.Millisecond)
			_, _ = gruRuntime.Conn().RequestWithContext(requestCtx, protocol.InterRegionObservabilitySubject("sfo", leaf),
				[]byte(`{"version":1}`))
			requestCancel()
		}
	}
	if err := gruRuntime.Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	if subject, got := sibling.awaitMessage(t, "ts.", 500*time.Millisecond); got {
		t.Fatalf("FRA's leaf intercepted %q addressed to SFO", subject)
	}

	// FRA cannot speak for SFO either: its health is refused and the link closes.
	impostor := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-impostor.creds", "fra"))
	impostor.publish(t, protocol.RegionHealthSubject("sfo"), "", []byte("forged"))
	if reason := impostor.awaitClose(t); !strings.Contains(reason, "Permissions Violation for Publish") {
		t.Fatalf("FRA published SFO's health; link closed with %q", reason)
	}
	resetter := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-reset.creds", "fra"))
	resetter.publish(t, protocol.JSConsumerResetSubject(protocol.JSDomainAPIPrefix("gru"), protocol.GlobalControlStream,
		protocol.GlobalMirrorConsumer("sfo")), "", []byte(`{"seq":99}`))
	if reason := resetter.awaitClose(t); !strings.Contains(reason, "Permissions Violation for Publish") {
		t.Fatalf("FRA reset SFO's mirror consumer; link closed with %q", reason)
	}
	// A user signed by the interregion account identity key rather than a
	// child's scoped key gets the deny-all defaults, even for FRA's subjects.
	identity := dialRawLeaf(ctx, t, addr, leafTLS, gru.leafCredentials(t, "identity.creds"))
	identity.publish(t, protocol.RegionHealthSubject("fra"), "", []byte("unscoped"))
	if reason := identity.awaitClose(t); !strings.Contains(reason, "Permissions Violation for Publish") {
		t.Fatalf("unscoped leaf user published; link closed with %q", reason)
	}
	// Its own region's subjects still cross.
	own := dialRawLeaf(ctx, t, addr, leafTLS, gru.childLeafCredentials(t, "fra-own.creds", "fra"))
	defer own.close()
	health := make(chan *nats.Msg, 4)
	healthSub, err := gruRuntime.Conn().ChanSubscribe(protocol.RegionHealthSubject("fra"), health)
	if err != nil {
		t.Fatal(err)
	}
	defer healthSub.Unsubscribe()
	if err := gruRuntime.Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	for {
		own.publish(t, protocol.RegionHealthSubject("fra"), "", []byte("fra-health"))
		select {
		case msg := <-health:
			if string(msg.Data) == "fra-health" {
				return
			}
		case <-time.After(100 * time.Millisecond):
		case <-ctx.Done():
			t.Fatal("FRA's own health did not cross")
		}
	}
}

func TestChildLeafPermissionsAreScopedToTheSubtree(t *testing.T) {
	t.Parallel()

	// IAD dials SFO; SFO and FRA dial GRU.
	topology := HubAndSpoke("gru", []string{"fra", "iad", "sfo"}).WithSpokeParent("iad", "sfo")
	subtrees := topology.Subtrees("gru")
	if !slices.Equal(subtrees["sfo"], []string{"iad", "sfo"}) || !slices.Equal(subtrees["fra"], []string{"fra"}) || len(subtrees) != 2 {
		t.Fatalf("subtrees = %v", subtrees)
	}
	if spoke := topology.Subtrees("sfo"); len(spoke) != 1 || !slices.Equal(spoke["iad"], []string{"iad"}) {
		t.Fatalf("sfo subtrees = %v", spoke)
	}
	contract := InterRegionContract{Cell: "gru", Peers: topology.Peers("gru"), GlobalHome: "gru", Subtrees: subtrees}
	sfo := contract.ChildLeafPermissions("sfo")
	reset := func(region string) string {
		return protocol.JSConsumerResetSubject(protocol.JSDomainAPIPrefix("gru"), protocol.GlobalControlStream,
			protocol.GlobalMirrorConsumer(region))
	}
	for _, own := range []string{"sfo", "iad"} {
		if !slices.Contains(sfo.Pub.Allow, protocol.RegionHealthSubject(own)) || !slices.Contains(sfo.Pub.Allow, reset(own)) ||
			!slices.Contains(sfo.Sub.Allow, protocol.Regional(own, "query", ">")) ||
			!slices.Contains(sfo.Sub.Allow, protocol.InterRegionGlobalDeliverSubject(own)) {
			t.Errorf("SFO's leaf lacks its subtree region %s", own)
		}
	}
	for _, foreign := range []string{"fra", "gru"} {
		if slices.Contains(sfo.Pub.Allow, protocol.RegionHealthSubject(foreign)) || slices.Contains(sfo.Pub.Allow, reset(foreign)) ||
			slices.Contains(sfo.Sub.Allow, protocol.Regional(foreign, "query", ">")) ||
			slices.Contains(sfo.Sub.Allow, protocol.InterRegionGlobalDeliverSubject(foreign)) {
			t.Errorf("SFO's leaf may act for %s", foreign)
		}
	}
	if unknown := contract.ChildLeafPermissions("lhr"); !denyAll(unknown) {
		t.Fatalf("unknown child permissions = %+v", unknown)
	}

	keys := newTestRegionKeys(t)
	system, cell, interregion := keys.claims(contract, 2)
	if err := contract.verify(system, cell, interregion, 2); err != nil {
		t.Fatal(err)
	}
	if !denyAll(interregion.DefaultPermissions) {
		t.Fatal("interregion defaults are not deny-all")
	}
	scopeOf := func(claim *jwt.AccountClaims, child string) *jwt.UserScope {
		for _, scope := range claim.SigningKeys {
			if user, ok := scope.(*jwt.UserScope); ok && user.Role == child {
				return user
			}
		}
		t.Fatalf("no scope for %s", child)
		return nil
	}
	mutations := map[string]func(*jwt.AccountClaims){
		"unscoped signing key": func(claim *jwt.AccountClaims) {
			extra, _ := nkeys.CreateAccount()
			public, _ := extra.PublicKey()
			claim.SigningKeys.Add(public)
		},
		"missing child scope": func(claim *jwt.AccountClaims) {
			delete(claim.SigningKeys, scopeOf(claim, "fra").Key)
		},
		"widened template": func(claim *jwt.AccountClaims) {
			scopeOf(claim, "fra").Template.Pub.Allow.Add(protocol.RegionHealthSubject("sfo"))
		},
		"sibling template": func(claim *jwt.AccountClaims) {
			scopeOf(claim, "fra").Template.Permissions = contract.ChildLeafPermissions("sfo")
		},
		"client connections": func(claim *jwt.AccountClaims) {
			scopeOf(claim, "fra").Template.AllowedConnectionTypes = jwt.StringList{jwt.ConnectionTypeStandard}
		},
		"bearer users":   func(claim *jwt.AccountClaims) { scopeOf(claim, "fra").Template.BearerToken = true },
		"unknown role":   func(claim *jwt.AccountClaims) { scopeOf(claim, "fra").Role = "lhr" },
		"duplicate role": func(claim *jwt.AccountClaims) { scopeOf(claim, "fra").Role = "sfo" },
		"permissive defaults": func(claim *jwt.AccountClaims) {
			claim.DefaultPermissions = contract.LeafPermissions()
		},
	}
	for name, mutate := range mutations {
		system, cell, interregion := keys.claims(contract, 2)
		mutate(interregion)
		if err := contract.verify(system, cell, interregion, 2); err == nil {
			t.Errorf("%s: widened interregion account verified", name)
		}
	}
}

func TestIssueLinkUserCarriesOnlyTheLinkClaim(t *testing.T) {
