func testJWTUserCredentialsWithKey(t *testing.T, root, name string, account nkeys.KeyPair, accountID string, user nkeys.KeyPair, publish, subscribe []string) string {
	t.Helper()
	userID, err := user.PublicKey()
	if err != nil {
