	}
	claim := jwt.NewUserClaims(userID)
	claim.IssuerAccount = accountID
	if publish != nil {
		claim.Pub.Allow = publish
	}
	if subscribe != nil {
		claim.Sub.Allow = subscribe
	}
	raw, err := claim.Encode(account)
	if err != nil {
		t.Fatal(err)
	}
	seed, err := user.Seed()
	if err != nil {
		t.Fatal(err)
	}
	creds, err := jwt.FormatUserConfig(raw, seed)
	if err != nil {
