func (natsLogger) Noticef(format string, v ...any) {
	logNATS(slog.LevelInfo, fmt.Sprintf(format, v...))
}

func (natsLogger) Warnf(format string, v ...any) {
	message := fmt.Sprintf(format, v...)
	level := slog.LevelWarn
	// A peer that is catching up logs this on every snapshot; it is routine.
	if strings.HasPrefix(message, "Metalayer blocking snapshot") {
		level = slog.LevelInfo
	}
	logNATS(level, message)
}

func (natsLogger) Fatalf(format string, v ...any) {
	logNATS(slog.LevelError, fmt.Sprintf(format, v...))
}

func (natsLogger) Errorf(format string, v ...any) {
	logNATS(slog.LevelError, fmt.Sprintf(format, v...))
}

func (natsLogger) Debugf(format string, v ...any) {
	logNATS(slog.LevelDebug, fmt.Sprintf(format, v...))
}

func (natsLogger) Tracef(format string, v ...any) {
	logNATS(slog.LevelDebug, fmt.Sprintf(format, v...))
}

func logNATS(level slog.Level, message string) {
	slog.Log(context.Background(), level, message, observability.ComponentKey, "nats")
}

// ErrorHandler logs an asynchronous client error that nats.go would otherwise
// print to stderr as plain text.
func ErrorHandler(conn *nats.Conn, sub *nats.Subscription, err error) {
	level := slog.LevelWarn
	if errors.Is(err, nats.ErrPermissionViolation) || errors.Is(err, nats.ErrAuthorization) {
		level = slog.LevelError
	}
	attrs := []any{observability.ComponentKey, "nats-client", "error", err}
	if conn != nil {
		attrs = append(attrs, "connection", conn.Opts.Name)
	}
	if sub != nil {
		attrs = append(attrs, "subject", sub.Subject)
	}
	slog.Log(context.Background(), level, "nats client error", attrs...)
}

logging.text:
func NewLogger(output io.Writer, config LogConfig, bus *EventBus, attrs ...slog.Attr) (*slog.Logger, error) {
	config, level, err := ParseLogConfig(config.Format, config.Level)
	if err != nil {
		return nil, err
	}
	if journalStream() {
		output = journalWriter{next: output}
	}
	options := &slog.HandlerOptions{Level: level, ReplaceAttr: utcTime}
	var handler slog.Handler
	if config.Format == "logfmt" {
		handler = slog.NewTextHandler(output, options)
	} else {
		handler = slog.NewJSONHandler(output, options)
	}
	if bus != nil {
		handler = &EventTee{next: handler, bus: bus, counters: newLogCounters(), repeats: newEventRepeats()}
	}
	handler = &redactingHandler{next: handler}
	if len(attrs) > 0 {
		handler = handler.WithAttrs(attrs)
	}
	return slog.New(handler), nil
}

// utcTime writes the record's own time in UTC, as record v1 requires. Only the
// top-level time key: a time attribute keeps the zone it was logged with.
func utcTime(groups []string, attr slog.Attr) slog.Attr {
	if attr.Key == slog.TimeKey && len(groups) == 0 && attr.Value.Kind() == slog.KindTime {
		attr.Value = slog.TimeValue(attr.Value.Time().UTC())
	}
	return attr
}

// journalWriter prefixes each record with its syslog priority, which journald
// stores as PRIORITY and strips from the message. slog writes a record in one
// Write call, so the prefix and the record reach journald together.
type journalWriter struct{ next io.Writer }

func (w journalWriter) Write(record []byte) (int, error) {
	if _, err := w.next.Write(append([]byte(journalPriority(record)), record...)); err != nil {
		return 0, err
	}
	return len(record), nil
}

var journalPriorities = []struct{ level, prefix string }{
	{"ERROR", "<3>"}, {"WARN", "<4>"}, {"INFO", "<5>"}, {"DEBUG", "<7>"},
}

// journalPriority reads the level of a JSON or logfmt record. The level comes
// before the message, so the earliest marker is the real level, not text that
// a message repeats. INFO is notice (<5>), not info, because INFO records are
// state changes and the watchdog drop-in's LogLevelMax=notice must keep them.
func journalPriority(record []byte) string {
	best, prefix := len(record), "<5>"
	for _, priority := range journalPriorities {
		for _, marker := range []string{`"level":"` + priority.level + `"`, "level=" + priority.level + " "} {
			if at := bytes.Index(record, []byte(marker)); at >= 0 && at < best {
				best, prefix = at, priority.prefix
			}
		}
	}
	return prefix
}

// ConfigureDefault installs logger as the process default. The standard
// library log package then writes through the same structured handler.
func ConfigureDefault(logger *slog.Logger) {
	if logger != nil {
		slog.SetDefault(logger)
	}
}

streamview.text:
func streamView(stream server.StreamDetail) observability.StreamView {
	view := observability.StreamView{Name: stream.Name, Messages: stream.State.Msgs, Bytes: stream.State.Bytes, Replicas: 1}
	configured := stream.Config != nil && stream.Config.Replicas > 0
	if configured {
		view.Replicas = stream.Config.Replicas
	}
	if cluster := stream.Cluster; cluster != nil {
		view.Leader = cluster.Leader
		// Without a configured factor, count peers from the cluster info.
		// It omits the leader from Replicas, but a leaderless group lists
		// every peer, this server included.
		peers := len(cluster.Replicas)
		if cluster.Leader != "" {
			peers++
		}
		if !configured && peers > view.Replicas {
			view.Replicas = peers
		}
		for _, replica := range cluster.Replicas {
			if replica == nil {
				continue
			}
			view.MaxReplicaLag = max(view.MaxReplicaLag, replica.Lag)
			if replica.Offline {
				view.OfflinePeers++
			}
		}
	}
	return view
}

userpermissions.text:
func userPermissions(cell string, user NKeyGrant) (*server.Permissions, error) {
	inbox := inboxPrefix(cell, user.PublicKey) + ".>"
	permissions := &server.Permissions{Subscribe: &server.SubjectPermission{Allow: []string{inbox}}}
	if user.Global && user.Role != "controller" {
		return nil, errors.New("only a controller NATS user may carry global home grants")
	}
	switch user.Role {
	case "host":
		if !cellName.MatchString(user.Node) {
			return nil, errors.New("host NATS user needs a valid node identity")
		}
		permissions.Publish = &server.SubjectPermission{Allow: []string{
			protocol.AgentObservation(cell, user.PublicKey, "*"),
		}}
	case "controller":
		if user.Node != "" {
			return nil, errors.New("controller NATS user must not carry a host node")
		}
		permissions.Publish = &server.SubjectPermission{Allow: []string{
			protocol.Regional(cell, ">"), protocol.Control(cell, ">"), "$JS.API.>", "$KV.>", "$O.>",
			"$JS.ACK.TS_DELIVERY_INTENTS.TS_DELIVERY_WORKER.>",
		}}
		for _, leaf := range protocol.InterRegionObservabilityLeaves() {
			permissions.Publish.Allow = append(permissions.Publish.Allow, protocol.AnyRegionObservabilitySubject(leaf))
		}
		permissions.Publish.Allow = append(permissions.Publish.Allow, protocol.AnyRegionQuerySubject())
		if user.Global {
			permissions.Publish.Allow = append(permissions.Publish.Allow, GlobalControllerPublishes()...)
			permissions.Publish.Allow = append(permissions.Publish.Allow, GlobalControllerRequests()...)
			permissions.Subscribe.Allow = append(permissions.Subscribe.Allow, GlobalControllerRequests()...)
		}
		permissions.Subscribe.Allow = append(permissions.Subscribe.Allow,
			ControllerSubscriptions(cell)...)
		// Read-only member telemetry: every controller answers observability
		// snapshot requests for its cell.
		permissions.Subscribe.Allow = append(permissions.Subscribe.Allow, protocol.ObservabilityGrant(cell))
	case "operator":
		if user.Node != "" {
			return nil, errors.New("operator NATS user must not carry a host node")
		}
		permissions.Publish = &server.SubjectPermission{Allow: []string(BrokerOperatorPublishPermissions(cell))}
	default:
		return nil, fmt.Errorf("invalid NATS user role %q", user.Role)
	}
	return permissions, nil
}

operatorpermissions.text:
func BrokerOperatorPublishPermissions(cell string) jwt.StringList {
	return jwt.StringList{
		protocol.DeliveryIntentSubject(cell), protocol.DeliveryArtifactAdmitSubject(cell), protocol.HostRegisterSubject(cell),
		protocol.PlacementApplySubject(cell), protocol.ManagedUpdatePrepareSubject(cell), protocol.MaterialPrepareSubject(cell),
		protocol.BackupOperationSubject(cell), protocol.BrokerClaimApplySubject(cell),
		protocol.TerminalSubject(cell, "plan"), protocol.TerminalSubject(cell, "apply"), protocol.TerminalSubject(cell, "status"),
		"$JS.API.INFO", "$JS.API.STREAM.INFO.TS_DELIVERY_INTENTS",
		"$JS.API.STREAM.INFO.OBJ_TS_ARTIFACTS",
		"$JS.API.STREAM.INFO.KV_TS_DELIVERY_ADMISSIONS",
		"$JS.API.STREAM.INFO.KV_TS_DELIVERY_OPERATIONS",
		"$JS.API.STREAM.INFO.KV_TS_HOST_STATE",
		"$JS.API.STREAM.INFO.TS_CONTROL_LOG",
		"$JS.API.STREAM.MSG.GET.OBJ_TS_ARTIFACTS",
		"$JS.API.STREAM.MSG.GET.KV_TS_DELIVERY_ADMISSIONS",
		"$JS.API.STREAM.MSG.GET.KV_TS_DELIVERY_OPERATIONS",
		"$JS.API.STREAM.MSG.GET.KV_TS_HOST_STATE",
		"$JS.API.STREAM.MSG.GET.TS_CONTROL_LOG",
		"$JS.API.CONSUMER.CREATE.OBJ_TS_ARTIFACTS.>",
		"$JS.API.CONSUMER.INFO.OBJ_TS_ARTIFACTS.*",
		"$JS.API.CONSUMER.DELETE.OBJ_TS_ARTIFACTS.*",
		"$JS.API.DIRECT.GET.OBJ_TS_ARTIFACTS",
		"$JS.API.DIRECT.GET.OBJ_TS_ARTIFACTS.>",
		"$JS.API.DIRECT.GET.KV_TS_DELIVERY_ADMISSIONS.>",
		"$JS.API.DIRECT.GET.KV_TS_DELIVERY_OPERATIONS.>",
		"$JS.API.DIRECT.GET.KV_TS_HOST_STATE.>",
		"$JS.API.DIRECT.GET.TS_CONTROL_LOG.>",
		"$O.TS_ARTIFACTS.>",
	}
}

// ControllerPublishes is the regional controller's publish surface. It also
// names every region's summary, decision and read-only query services by
// pattern, so no region needs its own grant; remote snapshots, journals and
// mutations stay out.
func ControllerPublishes(cell string) jwt.StringList {
	publishes := jwt.StringList{protocol.Regional(cell, ">"), protocol.Control(cell, ">"), "$JS.API.>", "$KV.>", "$O.>",
		protocol.Broker(cell, "ticket", ">"), protocol.Broker(cell, "fence", ">")}
	for _, leaf := range protocol.InterRegionObservabilityLeaves() {
		publishes.Add(protocol.AnyRegionObservabilitySubject(leaf))
	}
	publishes.Add(protocol.AnyRegionQuerySubject())
	return publishes
}

// ControllerSubscriptions is the exact regional request surface a controller
// serves, in issuer order. Private inbox and broker grants are added by callers.
func ControllerSubscriptions(cell string) []string {
	return []string{
		protocol.BrokerClaimApplySubject(cell), protocol.AgentObservation(cell, "*", "*"),
		protocol.DeliveryArtifactAdmitSubject(cell), protocol.HostRegisterSubject(cell),
		protocol.PlacementApplySubject(cell), protocol.ManagedUpdatePrepareSubject(cell),
		protocol.BackupOperationSubject(cell), protocol.TerminalSubject(cell, ">"),
		// The seed answers epoch-fenced slot replacement requests from a
		// non-seed authority leader. Material issued before this grant
		// existed lacks it; the request then has no responder and the
		// leader holds the slot, as before.
		protocol.MembershipReplaceSubject(cell),
		// Every controller collects its peers' signed rollout health proofs
		// (controller.rollouts.executor). Material issued before this grant
		// lacks it; such a controller sees no proofs, so its executor holds
		// every rollout in preflight and nothing moves.
		protocol.RolloutProofSubject(cell, ""),
		// Read-only query services this region answers for every region.
		protocol.Regional(cell, "query", ">"),
		// The global home builds the roster from every region's heartbeat.
		// Material issued before this grant lacks it; the home then keeps no
		// roster, and its peers keep their last one.
		protocol.AnyRegionHealthSubject(),
		// Every region's dashboard rollup (TS-805), carried by the link.
		// Material issued before this grant lacks it; such a follower's
		// global view stays empty and the leader holds only its own rollup.
		protocol.RegionRollupGrant,
	}
}

